  return _.flatMap(utilities, ([prefix, properties]) => {
    return _.flatMap(padding, (size, modifier) => {
      return defineClasses({
        [`${prefix}-${modifier}`]: _.mapValues(properties, value => value(size)),
      })
    })
  })
}

function defineMargin(margin) {
  return _.flatMap(margin, (size, modifier) => {
    return defineClasses({
      [`mt-${modifier}`]: {
        'margin-top': `${size}`,
      },
      [`mr-${modifier}`]: {
        'margin-right': `${size}`,
      },
      [`mb-${modifier}`]: {
        'margin-bottom': `${size}`,
      },
      [`ml-${modifier}`]: {
        'margin-left': `${size}`,
      },
      [`mx-${modifier}`]: {
        'margin-left': `${size}`,
        'margin-right': `${size}`,
      },
      [`my-${modifier}`]: {
        'margin-top': `${size}`,
        'margin-bottom': `${size}`,
      },
      [`m-${modifier}`]: {
        margin: `${size}`,
      },
    })
  })
}
